package dev.amenhancer.module.lyrics.online

/**
 * Removes the lines providers ship that are not lyrics.
 *
 * Every platform mixes its own bookkeeping into the timed body: NetEase, QQ Music and Kugou put
 * a block of `作词 / 作曲 / 编曲 / …` credits at 0-10 s — often without a colon
 * (`作词 周杰伦`) — QQ Music opens both lanes with a copyright notice
 * (`QQ音乐享有本翻译作品的著作权`, `TME享有本翻译作品的著作权`, `以下歌词翻译由…提供`),
 * QQ opens with a `歌名 - 歌手` header line, Kugou injects an app advertisement and a
 * `关注公众号` call to action, YouTube-sourced bodies carry `Provided to YouTube by …`,
 * `Auto-generated by YouTube` and `Released on: …`, instrumentals carry `纯音乐，请欣赏`,
 * and empty translation slots arrive as `//`. Left in place they render as lyric lines and push
 * every later line out of sync.
 *
 * Every lane goes through the same rules, in this order:
 * 1. placeholder shells (`//`, `…`, `♪`, `00:12.30`, anything without a single letter) go;
 * 2. platform and copyright lines (`©`, `℗`, `QQ音乐`, `未经许可`, …) go wherever they sit;
 * 3. credit lines go while the lane opens with a credit block (≥ [CREDIT_BLOCK_MIN] credit
 *    shapes inside the first [CREDIT_BLOCK_SCAN] lines) and the line starts within
 *    [CREDIT_WINDOW_MS]; a lone credit shape without a block is only dropped inside
 *    [SINGLE_CREDIT_WINDOW_MS], so a real lyric such as `作曲：上帝` at 0:30 survives;
 * 4. the `歌名 - 歌手 (英文名)` header goes when it matches the known song identity or — with
 *    no identity at all — when it opens the lane (≤ [HEADER_WINDOW_MS]) in the `A - B` shape
 *    and stays short;
 * 5. a line repeating the previous kept line within [DUPLICATE_WINDOW_MS] (punctuation and
 *    casing ignored) is a provider duplicate and goes.
 *
 * Credits only count when a key opens the line *and* carries a value (colon or whitespace +
 * content), so `曲终人散` and `词不达意` stay lyrics. Translation and romanization lanes run
 * the same rules minus the identity header, because their lines are keyed onto the original
 * lines by start time instead of by index.
 */
object LyricLineFilter {

    /** Credits never sit later than this; a later line with a credit shape is treated as a lyric. */
    const val CREDIT_WINDOW_MS = 60_000L

    /** A credit line is short; a longer line is treated as a lyric even inside the window. */
    const val CREDIT_MAX_LENGTH = 60

    /** How many leading lines are inspected to decide whether a credit block exists. */
    const val CREDIT_BLOCK_SCAN = 20

    /** How many credit-shaped lines inside that scan turn the lane into a "has credits" lane. */
    const val CREDIT_BLOCK_MIN = 2

    /** Lines inspected for the opening credit/header block. */
    const val LEADING_SCAN = 20

    /** Only the first minute can open with a block; later lines are lyrics. */
    const val LEADING_WINDOW_MS = 60_000L

    /** Without a credit block a lone credit shape is only dropped while the song is barely started. */
    /** Two identical lines closer than this are a provider duplicate. */
    const val DUPLICATE_WINDOW_MS = 3_000L

    /** A `歌名 - 歌手` header only ever opens a lane. */
    const val HEADER_WINDOW_MS = 3_000L

    /** A header carrying no identity proof still has to be short. */
    const val HEADER_MAX_LENGTH = 80

    /** A platform call to action is short; a lyric that merely mentions the word is not. */
    const val CTA_MAX_LENGTH = 30

    /** `关注` may run into a word this short (`关注我们`) before it stops being a CTA. */
    const val CTA_OPEN_MAX_LENGTH = 6

    /**
     * Credit keys, longest first so `制作人` wins over `制作` and `词曲` over `词`.
     * The alternation backtracks anyway; the order only keeps the pattern readable.
     */
    private val CREDIT_KEYS = listOf(
        "作词人", "作曲人", "词曲", "编曲人", "制作人", "监制", "出品", "发行",
        "录音师", "录音室", "录音助理", "人声录音", "人声编辑", "混音师", "母带师", "和声编写",
        "LRC制作", "歌词制作", "翻译贡献者",
        "作词", "作曲", "编曲", "制作", "OP", "SP", "词", "曲", "演唱", "原唱", "和声",
        "录音", "混音", "母带", "吉他", "贝斯", "鼓", "键盘", "弦乐", "统筹", "企划", "宣发",
        "翻译", "校对", "字幕", "后期",
    ).sortedByDescending { key -> key.length }

    /**
     * `词：周杰伦`, `作词 : 周杰伦`, `作词 周杰伦`: the key opens the line and is followed by a
     * colon or by whitespace + a value. `曲终人散` has neither, so it stays a lyric.
     */
    private val CREDIT_ZH = Regex(
        "^\\s*(?:" + CREDIT_KEYS.joinToString("|") + ")(?:\\s*[:：]|\\s+\\S)",
    )

    private val CREDIT_EN_BY = Regex(
        "^\\s*(?:lyrics|composed|arranged|produced|mixed|mastered|written|performed)\\s+by\\b",
        RegexOption.IGNORE_CASE,
    )

    private val CREDIT_EN_RECORDED = Regex(
        "^\\s*recorded\\s+at\\b",
        RegexOption.IGNORE_CASE,
    )

    /** `Vocals: 周杰伦`, `Vocals by 周杰伦`, or the bare `Vocals` label. */
    private val CREDIT_EN_VOCALS = Regex(
        "^\\s*vocals?\\b\\s*(?:[:：].*|by\\s+\\S.*)?\$",
        RegexOption.IGNORE_CASE,
    )

    /** Lines a platform adds about itself instead of the song. Matched anywhere, at any time. */
    private val PLATFORM_NOISE = listOf(
        "©", "℗", "copyright", "all rights reserved", "provided to youtube by",
        "auto-generated by", "released on", "under exclusive license",
        "qq音乐", "网易云", "酷狗", "酷我",
        "歌词来自", "歌词由", "歌词提供", "未经许可", "纯音乐", "暂无歌词", "没有填词", "扫码",
        "享有本翻译作品的著作权", "以下歌词翻译由", "本翻译作品", "音乐创作如此简单", "app制作",
    )

    /** `此歌曲由Vemus未音APP制作` — the generator advertises itself. */
    private val SELF_PROMO = Regex("此歌曲由.*制作")

    /** `TME享有本翻译作品的著作权`; the word boundary keeps `treatment` a lyric. */
    private val TME = Regex("\\bTME\\b")

    /** Marketing verbs. They only count in a call-to-action shape, see [isCallToAction]. */
    private val CTA_MARKERS = listOf("关注", "订阅")

    /** Words that turn `关注` into `关注公众号` and keep `我一直关注着你` a lyric. */
    private val CTA_CONTEXT = listOf(
        "公众号", "官方", "我们", "账号", "微信", "频道", "获取", "下载", "更多", "二维码",
        "扫一扫", "QQ", "群",
    )

    /** `晴天 - 周杰伦 (Jay Chou)`: any spacing, only used when the song identity proves it. */
    private val HEADER_SEPARATOR = Regex("\\s*[-–—]\\s*")

    /** Without identity the spacing is the only thing telling a header from a lyric line. */
    private val HEADER_SHAPE = Regex("\\s+[-–]\\s+")

    /**
     * Filters every lane of [result]. [songTitle] and [songArtist], when known, let the filter
     * drop the `歌名 - 歌手` header line providers put above the credits.
     */
    fun filter(
        result: LyricsResult,
        songTitle: String? = null,
        songArtist: String? = null,
    ): LyricsResult = result.copy(
        original = sanitize(result.original, songTitle, songArtist, identityHeader = true),
        translated = result.translated?.let { sanitize(it, null, null, identityHeader = false) },
        romanization = result.romanization?.let { sanitize(it, null, null, identityHeader = false) },
    )

    private fun sanitize(
        lines: List<LyricsLine>,
        songTitle: String?,
        songArtist: String?,
        identityHeader: Boolean,
    ): List<LyricsLine> {
        if (lines.isEmpty()) return lines
        val bodies = lines.map(::text)
        val creditBlock = bodies.take(CREDIT_BLOCK_SCAN)
            .withIndex()
            .count { (index, body) -> isCreditShape(body, lines[index].start, index) } >= CREDIT_BLOCK_MIN

        // Pass 1: which lines do the rules reject?
        val rejected = BooleanArray(lines.size)
        for (index in lines.indices) {
            val body = bodies[index]
            rejected[index] = isPlaceholder(body) ||
                isPlatformNoise(body) ||
                isCredit(body, lines[index].start, index, creditBlock) ||
                (identityHeader && isHeader(body, lines[index].start, songTitle, songArtist))
        }

        // Pass 2: the opening block is a unit. Everything up to the LAST line the rules rejected
        // inside the leading window goes with it, so a provider header the rules cannot name (or a
        // stray production note between credits) cannot survive as a fake first lyric.
        var lastJunk = -1
        var scanned = 0
        for (index in lines.indices) {
            if (scanned >= LEADING_SCAN) break
            scanned += 1
            if (lines[index].start > LEADING_WINDOW_MS) break
            if (rejected[index]) lastJunk = index
        }

        val kept = ArrayList<LyricsLine>(lines.size)
        var previousBody = ""
        var previousStart = -DUPLICATE_WINDOW_MS - 1L
        for (index in lines.indices) {
            if (rejected[index]) continue
            if (index <= lastJunk) continue
            val line = lines[index]
            val body = bodies[index]
            if (isDuplicate(body, line.start, previousBody, previousStart)) continue
            kept += line
            previousBody = body
            previousStart = line.start
        }
        return kept
    }

    private fun text(line: LyricsLine): String =
        line.words.joinToString("") { word -> word.text }.trim()

    /**
     * A line without a single letter carries no lyric: `♪`, `…`, `//`, `•••`, `00:12.30`,
     * `1 2 3 4`. Provider bodies only reach this state through a broken LRC conversion or an
     * empty slot, never because something was sung.
     */
    private fun isPlaceholder(body: String): Boolean =
        body.isEmpty() || body.none { glyph -> glyph.isLetter() }

    private fun isPlatformNoise(body: String): Boolean {
        val lower = body.lowercase()
        if (PLATFORM_NOISE.any { marker -> lower.contains(marker) }) return true
        if (SELF_PROMO.containsMatchIn(body)) return true
        if (TME.containsMatchIn(body)) return true
        return isCallToAction(body)
    }

    /**
     * `关注公众号`, `订阅频道`, `关注` open the line, or name a channel. A lyric that only
     * mentions the word (`我一直关注着你`) is left alone.
     */
    private fun isCallToAction(body: String): Boolean {
        if (body.length > CTA_MAX_LENGTH) return false
        val marker = CTA_MARKERS.firstOrNull { word -> body.contains(word) } ?: return false
        if (opensWithCall(body, marker)) return true
        return CTA_CONTEXT.any { word -> body.contains(word, ignoreCase = true) }
    }

    /**
     * `关注`, `关注我们`, `关注【酷狗音乐】`: the marker either ends the line, opens a short
     * line, or runs into punctuation. `关注着你的背影` keeps running into the lyric, so it stays.
     */
    private fun opensWithCall(body: String, marker: String): Boolean {
        val trimmed = body.trimStart()
        if (!trimmed.startsWith(marker)) return false
        if (trimmed.length <= CTA_OPEN_MAX_LENGTH) return true
        val rest = trimmed.substring(marker.length)
        val next = rest.firstOrNull() ?: return true
        return next.isWhitespace() || !next.isLetterOrDigit()
    }

    /** A credit line: a credit key, short, and inside the opening window or the first lines. */
    private fun isCreditShape(body: String, startMs: Long, index: Int): Boolean =
        body.length <= CREDIT_MAX_LENGTH &&
            (startMs <= CREDIT_WINDOW_MS || index < CREDIT_BLOCK_SCAN) &&
            matchesCreditKey(body)

    private fun matchesCreditKey(body: String): Boolean {
        val probe = flat(body)
        return CREDIT_ZH.containsMatchIn(probe) ||
            CREDIT_EN_BY.containsMatchIn(probe) ||
            CREDIT_EN_RECORDED.containsMatchIn(probe) ||
            CREDIT_EN_VOCALS.matches(probe)
    }

    /**
     * Providers mix ASCII, non-breaking and ideographic spaces (`作词　周杰伦`); Java spells out
     * only the ASCII one in `\s`, so the ideographic space is folded before matching. The line
     * itself keeps its original text.
     */
    private fun flat(body: String): String =
        body.replace('\u3000', ' ').replace('\u00A0', ' ')

    /**
     * A credit block removes its credit shapes up to [CREDIT_WINDOW_MS]; a lone credit shape is
     * only removed inside [SINGLE_CREDIT_WINDOW_MS], which keeps `作曲：上帝` at 0:30 a lyric.
     */
    private fun isCredit(body: String, startMs: Long, index: Int, creditBlock: Boolean): Boolean =
        // No song writes a credit as a lyric, so a credit-shaped line goes wherever it appears.
        isCreditShape(body, startMs, index)

    private fun isDuplicate(
        body: String,
        startMs: Long,
        previousBody: String,
        previousStart: Long,
    ): Boolean =
        previousBody.isNotEmpty() &&
            startMs - previousStart <= DUPLICATE_WINDOW_MS &&
            normalize(body) == normalize(previousBody)

    /** `他说：别回头` and `他说 别回头` are the same provider line once punctuation is gone. */
    private fun normalize(body: String): String =
        body.lowercase().filter { glyph -> glyph.isLetterOrDigit() }

    private fun isHeader(
        body: String,
        startMs: Long,
        songTitle: String?,
        songArtist: String?,
    ): Boolean {
        val title = songTitle?.trim().orEmpty()
        val artist = songArtist?.trim().orEmpty()
        val probe = flat(body)
        if ((title.isNotEmpty() || artist.isNotEmpty()) &&
            startMs <= CREDIT_WINDOW_MS &&
            matchesIdentity(probe, title, artist)
        ) {
            return true
        }
        // No identity (or a header that disagrees with it): the shape alone has to earn the drop,
        // so the line must open the lane and carry the one separator a `歌名 - 歌手` header has.
        return startMs <= HEADER_WINDOW_MS &&
            probe.length <= HEADER_MAX_LENGTH &&
            isTitleArtistShape(probe)
    }

    private fun matchesIdentity(body: String, title: String, artist: String): Boolean {
        val parts = HEADER_SEPARATOR.split(body)
        if (parts.size < 2) return false
        val left = parts.first().trim()
        val right = parts.last().trim()
        if (left.isEmpty() || right.isEmpty()) return false
        val leftMatches = title.isNotEmpty() && left.contains(title, ignoreCase = true)
        val rightMatches = artist.isNotEmpty() && right.contains(artist, ignoreCase = true)
        return leftMatches && rightMatches
    }

    /** Exactly two non-empty sides around the separator; `我们 - 走散了` only counts at 0-3 s. */
    private fun isTitleArtistShape(body: String): Boolean {
        val parts = HEADER_SHAPE.split(body)
        if (parts.size != 2) return false
        return parts.all { part -> part.isNotBlank() }
    }
}
